function validate([citations]) {
  if (!Array.isArray(citations) || citations.length < 1 || citations.length > 100000) return 'citations needs 1 to 10^5 values.';
  for (let i = 0; i < citations.length; i++) {
    const c = citations[i];
    if (!Number.isInteger(c) || c < 0 || c > 1000) return 'Each citation count is a whole number from 0 to 1000.';
    if (i > 0 && citations[i - 1] > c) return 'citations must be sorted from smallest to largest.';
  }
  return null;
}

