function hIndex(citations) {
  const n = citations.length;
  let left = 0;
  let right = n;

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (citations[mid] >= n - mid) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return n - left;
}

