function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const style = rand();
  const top = size === 'large' ? (style < 0.3 ? 1000 : 300 + Math.floor(rand() * 2000)) : (style < 0.15 ? 0 : 1 + Math.floor(rand() * 14));
  const citations = Array.from({ length: n }, () => Math.min(1000, Math.floor(rand() * (top + 1))));
  citations.sort((a, b) => a - b);
  return [citations];
}
